."}],"arrivee":[{"id":"ar-1","texte":"Regarder le cuir chevelu et les locks avant de commencer : irritation, plaie, pellicules, résidus, lock amincie à la racine. Le dire à la cliente et le noter sur sa fiche.","source":"pratique"},{"id":"ar-2","texte":"Lui demander sa routine et le rendu qu’elle veut.","source":"pratique"}],"etapes":[{"id":"et-1","texte":"Lavage.","source":"catalogue"},{"id":"et-2","texte":"Démêler mouillé, avec un soin, aux doigts ou au peigne à dents larges, des pointes vers la racine. Jamais à sec.","source":"pratique"},{"id":"et-3","texte":"Définition des boucles, section par section.","source":"catalogue"},{"id":"et-4","texte":"Styling.","source":"catalogue"},{"id":"et-5","texte":"Séchage à chaleur douce.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"Laver toutes les 1 à 3 semaines.","source":"pratique"},{"id":"co-2","texte":"Dormir avec un bonnet en satin ou en soie.","source":"laboratoire"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : court 1 h, mi-long 1 h 15, long 1 h 30.","source":"catalogue"},{"id":"su-2","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"sv-stu-c-eve-c":{"serviceId":"sv-stu-c-eve-c","code":"STU·C·EVE","titre":"CÉLÉBRER · Coiffure d’événement","validee":{"numero":1,"le":"2026-11-25T09:41:34.089Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"La coiffure d’une cérémonie, d’un gala, d’une occasion : chignon ou styling sophistiqué.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"La cliente qui a un événement.","source":"catalogue"}],"produits":[{"id":"pr-1","texte":"Épingles, élastiques, produits de finition, ornements.","source":"catalogue","aValider":"Références à inscrire."}],"arrivee":[{"id":"ar-1","texte":"Lui demander l’heure et la durée de l’événement, la tenue, et une photo de ce qu’elle veut.","source":"pratique"},{"id":"ar-2","texte":"Cheveux ou locks propres et secs avant de coiffer.","source":"pratique"},{"id":"ar-3","texte":"Regarder le contour : sur un contour clairsemé, pas de coiffure qui tire.","source":"pratique"}],"etapes":[{"id":"et-1","texte":"Chignon ou styling sophistiqué.","source":"catalogue"},{"id":"et-2","texte":"Aucune tension à la racine : si la cliente dit que ça tire, on desserre tout de suite.","source":"pratique"},{"id":"et-3","texte":"Lui faire bouger la tête : rien ne doit tirer ni glisser.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"Défaire la coiffure après l’événement : elle n’est pas faite pour être gardée.","source":"pratique"},{"id":"co-2","texte":"Si elle tire ou donne mal à la tête, la desserrer sans attendre.","source":"pratique"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : court 1 h, mi-long 1 h 30, long 2 h.","source":"catalogue"},{"id":"su-2","texte":"Compris dans : Forfait VÈKPÈ™ × GBÈJÍ™.","source":"catalogue"}]}}},"sv-stu-c-sik-1-c":{"serviceId":"sv-stu-c-sik-1-c","code":"STU·C·SIK·1","titre":"CÉLÉBRER · Le Grand Jour Essentiel","validee":{"numero":1,"le":"2026-11-25T09:41:34.422Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"La coiffure du jour J, en salon, sans essai préalable.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"La mariée ou la cliente du grand jour qui n’a pas pris d’essai.","source":"catalogue"}],"produits":[{"id":"pr-1","texte":"Épingles, élastiques, produits de finition, ornements et voile s’il y en a.","source":"catalogue","aValider":"Références à inscrire."}],"arrivee":[{"id":"ar-1","texte":"Il n’y a pas eu d’essai : s’accorder sur la coiffure avant de commencer, photo à l’appui, et redire ce qui est faisable dans le temps prévu.","source":"pratique"},{"id":"ar-2","texte":"Lui demander l’heure de la cérémonie, la tenue, les ornements.","source":"pratique"},{"id":"ar-3","texte":"Cheveux ou locks propres et secs.","source":"pratique"},{"id":"ar-4","texte":"Regard