aValider":"Les sept huiles : à nommer."},{"id":"pr-3","texte":"Casque vapeur.","source":"catalogue"}],"arrivee":[{"id":"ar-1","texte":"Regarder le cuir chevelu et les locks avant de commencer : irritation, plaie, pellicules, résidus, lock amincie à la racine. Le dire à la cliente et le noter sur sa fiche.","source":"pratique"},{"id":"ar-2","texte":"Locks propres : sur des locks chargées de résidus, on lave ou on purifie d’abord (WÈWÈ™ + DÀNDÀN™ existe pour cela).","source":"pratique"},{"id":"ar-3","texte":"Le DÀNDÀN™ contient des huiles essentielles : demander à la cliente si elle y est allergique, si elle est enceinte ou allaite.","source":"pratique","aValider":"À décider par la Maison : la règle pour la femme enceinte et pour l’enfant. Repères relevés : avis médical d’abord pendant la grossesse (Tisserand Institute) ; ni camphre, ni eucalyptol, ni menthol avant 3 ans (ANSM)."}],"etapes":[{"id":"et-1","texte":"Huiles végétales légères sur les longueurs, lock par lock.","source":"catalogue"},{"id":"et-2","texte":"Huiles essentielles et beurres.","source":"catalogue"},{"id":"et-3","texte":"Masque aux sept huiles.","source":"catalogue"},{"id":"et-4","texte":"Pose à la vapeur.","source":"catalogue","aValider":"Temps sous vapeur : à fixer par la Maison. Repère relevé : 20 à 30 minutes pour un masque (dermatologue citée par Healthline)."},{"id":"et-5","texte":"Rincer ou non, et comment.","source":"pratique","aValider":"À écrire : un soin gras mal rincé laisse des résidus dans la lock."},{"id":"et-6","texte":"Sécher complètement, jusqu’au cœur des locks : une lock restée humide prend une odeur et peut moisir.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"L’effet tient quelques jours.","source":"catalogue"},{"id":"co-2","texte":"Dormir avec un bonnet en satin ou en soie.","source":"laboratoire"},{"id":"co-3","texte":"À la maison, peu d’huile et jamais de cire ni de crème épaisse : ce qui reste dans la lock devient résidu.","source":"pratique"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : court 1 h, mi-long 1 h 10, long 1 h 20.","source":"catalogue"},{"id":"su-2","texte":"Compris dans : WÈWÈ™ + DÀNDÀN™ ; Le Protocole Post-Couleur ; Abonnement : GBÈJÍ™ Trimestriel ; Le Moment ; Abonnement : GBÈJÍ™ Annuel ; Le Moment Cuir chevelu.","source":"catalogue"},{"id":"su-3","texte":"Compris aussi dans les créations VÈKPÈ™ et les couleurs YÈKPÈ™, le jour même.","source":"catalogue"},{"id":"su-4","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"sv-plt-10-l":{"serviceId":"sv-plt-10-l","code":"PLT·10","titre":"DÀNDÀN™ Léger · L’hydratation douce","validee":{"numero":1,"le":"2026-11-25T09:41:35.473Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Hydrater et nourrir les locks tout en douceur, avec une sélection d’huiles.","source":"catalogue"},{"id":"ob-2","texte":"À la sortie : des locks souples, hydratées et nourries, pendant quelques jours.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"Cheveux secs, fragiles, sans éclat, ou après une décoloration ou une coloration.","source":"catalogue"}],"produits":[{"id":"pr-1","texte":"Une sélection d’huiles.","source":"catalogue","aValider":"Lesquelles, et ce qui distingue le Léger du DÀNDÀN™ aux sept huiles (pas de masque ? pas de vapeur ?) : à écrire."}],"arrivee":[{"id":"ar-1","texte":"Regarder le cuir chevelu et les locks avant de commencer : irritation, plaie, pellicules, résidus, lock amincie à la racine. Le dire à la cliente et le noter sur sa fiche.","source":"pratique"},{"id":"ar-2","texte":"Locks propres avant le soin.","source":"pratique"},{"id":"ar-3","texte":"Si la sélection contient des huiles essentielles : demander à la cliente si elle y est allergique, si elle est enceinte ou allaite.","source":"pratique","aValider":"À décider par la Maison : la règle pour la femme enceinte et pour l’enfant. Repères relevés : avis médical d’abord pendant la grossesse (Tisserand Institute) ; ni camphre, ni eucalyptol, ni menthol avant 3 ans (ANSM)."}],"etapes":[{"id":"et-1","texte":"Appliquer la sélection d’huiles sur les longueurs, lock par lock.","source":"catalogue","aValider":"Temps de pose, vapeur ou non, rinçage ou non : à écrire."},{"id":"et-2","texte":"Sécher complètement, jusqu’au cœur des locks : une lock restée humide prend une odeur et peut moisir.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"L’effet tient quelques jours.","source":"catalogue"},{"id":"co-2","texte":"Dormir avec un bonnet en satin ou en soie.","source":"laboratoire"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : 40 min.","source":"catalogue"},{"id":"su-2","texte":"Compris dans : Le Protocole Post-Couleur.","source":"catalogue"},{"id":"su-3","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"sv-gbigbi-cure-trois":{"serviceId":"sv-gbigbi-cure-trois","code":"PLT·40·CUR","titre":"GBÌGBÌ™ · Cure de trois","validee":{"numero":1,"le":"2026-11-25T09:41:35.853Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Trois renforts GBÌGBÌ™ en six semaines, posés au carnet.","source":"catalogue"},{"id":"ob-2","texte":"Rendre dans l’ordre les prestations comprises, chacune selon sa propre fiche.","source":"pratique"}],"public":[{"id":"pu-1","texte":"La cliente qui a pris cette formule : vérifier qu’elle est bien inscrite au rendez-vous.","source":"pratique"}],"produits":[{"id":"pr-1","texte":"Ceux de chaque prestation comprise : voir sa fiche, dans le même rendez-vous.","source":"catalogue"}],"arrivee":[{"id":"ar-1","texte":"Relire ce qui se rend aujourd’hui et ce qui reste à venir dans la formule.","source":"pratique"},{"id":"ar-2","texte":"Puis les vérifications de chaque prestation comprise : voir sa fiche.","source":"catalogue"}],"etapes":[{"id":"et-1","texte":"GBÌGBÌ™ · Le Renfort : voir sa fiche.","source":"catalogue"}],"conseils":[{"id":"co-1","texte":"Ceux de chaque prestation rendue ce jour : voir sa fiche.","source":"catalogue"},{"id":"co-2","texte":"Poser avec elle la venue suivante avant son départ.","source":"pratique"}],"suivi":[{"id":"su-1","texte":"3 semaines après : GBÌGBÌ™ · Le Renfort.","source":"catalogue"},{"id":"su-2","texte":"6 semaines après : GBÌGBÌ™ · Le Renfort.","source":"catalogue"}]}}},"sv-plt-40-m":{"serviceId":"sv-plt-40-m","code":"PLT·40","titre":"GBÌGBÌ™ · Le Renfort","validee":{"numero":1,"le":"2026-11-25T09:41:36.260Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Le reconstituant de la Maison, en version modulaire : anti-casse, fermeture de fibre, renfort structurel.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"Locks fragilisées, qui cassent ou s’ouvrent.","source":"catalogue"},{"id":"pu-2","texte":"Après une couleur, les Protocoles de la Maison le posent à deux semaines (J+14) : « la couleur ouvre la cuticule, on la referme avant qu’elle ne casse ». Dans le programme de pousse, à J+56.","source":"maison"}],"produits":[{"id":"pr-1","texte":"Masque Reconstituant & Scellement (kératine, protéines de soie, karité).","source":"laboratoire","detail":"SH-PRE-P3","aValider":"Le Laboratoire écrit ce masque pour le lavage Prestige. À confirmer : est-ce le produit du GBÌGBÌ™ ? Sinon, inscrire le sien."}],"arrivee":[{"id":"ar-1","texte":"Regarder le cuir chevelu et les locks avant de commencer : irritation, plaie, pellicules, résidus, lock amincie à la racine. Le dire à la cliente et le noter sur sa fiche.","source":"pratique"},{"id":"ar-2","texte":"Les préparations du Laboratoire : étiquette lisible, encore dans leur délai de garde, aucune odeur rance.","source":"laboratoire"},{"id":"ar-3","texte":"Demander la date du dernier soin protéiné : trop rapprochés, ils rendent la fibre raide et cassante.","source":"pratique"},{"id":"ar-4","texte":"Locks propres avant le soin.","source":"pratique"}],"etapes":[{"id":"et-1","texte":"Appliquer le reconstituant sur les longueurs, lock par lock, en insistant sur les zones qui cassent ou s’ouvrent.","source":"catalogue"},{"id":"et-2","texte":"Temps de pose.","source":"catalogue","aValider":"À fixer : le Laboratoire ne le dit pas."},{"id":"et-3","texte":"Rincer jusqu’à ce que l’eau soit claire, en pressant les locks.","source":"pratique"},{"id":"et-4","texte":"Sécher complètement, jusqu’au cœur des locks : une lock restée humide prend une odeur et peut moisir.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"Manipuler les locks avec douceur les jours qui suivent : pas de coiffure serrée sur une fibre en reconstruction.","source":"pratique"},{"id":"co-2","texte":"Dormir avec un bonnet en satin ou en soie.","source":"laboratoire"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : 1 h 20.","source":"catalogue"},{"id":"su-2","texte":"Existe en cure de trois : trois renforts en six semaines.","source":"catalogue"},{"id":"su-3","texte":"Compris dans : Le Protocole Post-Couleur ; GBÌGBÌ™.","source":"catalogue"},{"id":"su-4","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"cwrt1r54mf":{"serviceId":"cwrt1r54mf","titre":"L’Épure · le nettoyage à l’aiguille","validee":{"numero":1,"le":"2026-11-25T09:41:36.601Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Nettoyer les locks à l’aiguille.","source":"catalogue","aValider":"Le catalogue n’a pas de description pour L’Épure. À écrire : ce qu’elle retire (peluches, résidus incrustés), et ce qu’elle promet."}],"public":[{"id":"pu-1","texte":"Les locks qui portent des peluches ou des résidus visibles que le lavage ne retire pas.","source":"pratique"},{"id":"pu-2","texte":"Pas sur une lock amincie ou fragile : le travail à l’aiguille l’affine encore.","source":"pratique"}],"produits":[{"id":"pr-1","texte":"Aiguille ou crochet fin, bonne lumière.","source":"catalogue","aValider":"Outil exact de la Maison : à inscrire."}],"arrivee":[{"id":"ar-1","texte":"Regarder le cuir chevelu et les locks avant de commencer : irritation, plaie, pellicules, résidus, lock amincie à la racine. Le dire à la cliente et le noter sur sa fiche.","source":"pratique"},{"id":"ar-2","texte":"Montrer à la cliente, lock en main, ce qui peut partir et ce qui est trop profond pour être retiré sans abîmer.","source":"pratique"}],"etapes":[{"id":"et-1","texte":"Laver d’abord : une partie des résidus part au lavage, et on voit mieux ce qui reste.","source":"pratique"},{"id":"et-2","texte":"Retirer les peluches une à une, à la pointe de l’outil, sans traverser la lock ni forcer.","source":"pratique"},{"id":"et-3","texte":"S’arrêter sur une lock qui s’ouvre ou s’affine : mieux vaut un résidu qu’une lock trouée.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"Foulard ou bonnet en satin la nuit, serviette en microfibre : ce sont les tissus pelucheux qui chargent les locks.","source":"pratique"},{"id":"co-2","texte":"Ni cire ni crème épaisse dans les locks.","source":"pratique"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : 1 h.","source":"catalogue"},{"id":"su-2","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"sv-sowa-controle":{"serviceId":"sv-sowa-controle","titre":"Sówà™ · Le Contrôle à J+7","validee":{"numero":1,"le":"2026-11-25T09:41:36.945Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Sept jours après le Rituel Sówà™ : regarder de nouveau le cuir chevelu et les locks, et faire la seconde application.","source":"maison"},{"id":"ob-2","texte":"La Société française de dermatologie demande une première application, suivie d’une seconde entre le 7e et le 10e jour.","source":"pratique"}],"public":[{"id":"pu-1","texte":"La cliente qui a fait son Rituel Sówà™ il y a 7 à 10 jours. Le contrôle lui est offert.","source":"maison"}],"produits":[{"id":"pr-1","texte":"Pouxit XF, lotion en flacon : diméticone à 4 %, dispositif médical. Il agit par action physique, en recouvrant les poux et les lentes.","source":"notice","detail":"Pouxit XF lotion, flacon de 100 ou 200 ml"},{"id":"pr-2","texte":"Shampoing Doux Essentiel de la Maison, peigne fin, cape et serviettes du rituel, gants à usage unique.","source":"maison","detail":"SH-ESS-P1"}],"arrivee":[{"id":"ar-1","texte":"Relire sur sa fiche la date du rituel : le contrôle se fait de 7 à 10 jours après.","source":"maison"},{"id":"ar-2","texte":"Lui demander ce qu’elle a vu depuis, et si son cuir chevelu a réagi au produit. S’il a rougi ou brûlé : pas de seconde application, on prévient la direction et on lui conseille de consulter.","source":"pratique"},{"id":"ar-3","texte":"Examiner le cuir chevelu avec elle, avec discrétion et sans jugement.","source":"catalogue"},{"id":"ar-4","texte":"Le flacon en main est bien Pouxit XF, en lotion. Si c’est une autre référence (Flash, shampooing, spray), cette fiche ne vaut pas : on suit la notice de ce flacon et on prévient la direction.","source":"maison"},{"id":"ar-5","texte":"La notice de la boîte fait foi : si elle diffère de cette fiche, c’est elle qu’on suit, et on prévient la direction.","source":"maison"},{"id":"ar-6","texte":"Âge : 6 mois révolus au moins.","source":"notice"},{"id":"ar-7","texte":"Cuir chevelu sans plaie ni lésion : le produit ne s’applique pas sur une peau lésée.","source":"notice"},{"id":"ar-8","texte":"Lui demander si elle a déjà réagi à un produit anti-poux : pas d’application en cas d’allergie à l’un de ses composants.","source":"notice"},{"id":"ar-9","texte":"Aucune flamme ni source de chaleur près d’elle tant que le produit est sur la tête : ni casque, ni sèche-cheveux, ni cigarette.","source":"notice"}],"etapes":[{"id":"et-1","texte":"Examen du cuir chevelu : poux vivants, lentes.","source":"catalogue"},{"id":"et-2","texte":"Protéger ses yeux et ses épaules. Essuyer tout de suite ce qui tombe au sol : le produit rend le sol glissant.","source":"notice"},{"id":"et-3","texte":"Sur des locks et un cuir chevelu secs, appliquer Pouxit XF lock par lock, jusqu’à tout recouvrir, cuir chevelu compris.","source":"notice","detail":"Assez pour tout recouvrir : la notice ne donne pas de dose"},{"id":"et-4","texte":"Laisser agir.","source":"notice","detail":"15 minutes"},{"id":"et-5","texte":"Sans mouiller avant, appliquer le shampoing directement sur les locks, faire mousser, puis rincer.","source":"notice"},{"id":"et-6","texte":"Refaire un shampoing si les locks restent grasses, puis rincer jusqu’à ce que l’eau soit claire.","source":"pratique"},{"id":"et-7","texte":"Retrait des lentes au peigne fin.","source":"catalogue"},{"id":"et-8","texte":"Le peigne ne traverse pas une lock : le passer aux racines et sur les cheveux libres, sans défaire les locks.","source":"pratique"},{"id":"et-9","texte":"Une fois le produit entièrement retiré, sécher complètement, jusqu’au cœur des locks.","source":"pratique"},{"id":"et-10","texte":"Après elle : cape et serviettes lavées à 60 °C, peigne fin lavé puis mis de côté 3 jours.","source":"maison"}],"conseils":[{"id":"co-1","texte":"Regarder de nouveau la tête cinq jours plus tard, à J+12. S’il reste des poux vivants, revenir nous voir ou consulter.","source":"pratique"},{"id":"co-2","texte":"Draps, taies, bonnets, foulards et serviettes : lavés à 60 °C, ou enfermés 10 jours dans un sac.","source":"pratique"},{"id":"co-3","texte":"Peignes et brosses : lavés, puis mis de côté 3 jours.","source":"pratique"},{"id":"co-4","texte":"Regarder les têtes de toute la maison. Seules celles qui portent des poux vivants se traitent.","source":"pratique"},{"id":"co-5","texte":"Prévenir l’école ou la garderie, pour que les autres têtes soient regardées.","source":"pratique"},{"id":"co-6","texte":"Le soin hydratant DÀNDÀN™ peut maintenant se poser.","source":"maison"}],"suivi":[{"id":"su-1","texte":"Offert : il fait partie du Rituel Sówà™.","source":"maison"},{"id":"su-2","texte":"Durée au catalogue : 45 min. Il se pose de 1 à 2 semaines après la dernière venue ; le Trône avertit en dehors.","source":"catalogue"},{"id":"su-3","texte":"Si des poux vivants sont encore là au contrôle : prévenir la direction, qui décide de la suite. Pour des cheveux qu’on ne peut pas peigner, l’Université de Californie décrit trois applications espacées de 5 à 6 jours.","source":"maison"},{"id":"su-4","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"sv-plt-30-cur":{"serviceId":"sv-plt-30-cur","code":"PLT·30·CUR","titre":"VÍVÍVÓ™ · Cure de trois","validee":{"numero":1,"le":"2026-11-25T09:41:37.279Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Trois séances de l’activateur de pousse VÍVÍVÓ™.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"Les clientes du VÍVÍVÓ™ qui s’engagent sur trois séances : voir sa fiche pour qui l’éviter.","source":"catalogue"}],"produits":[{"id":"pr-1","texte":"Ceux du VÍVÍVÓ™ : voir sa fiche.","source":"catalogue"}],"arrivee":[{"id":"ar-1","texte":"Relire sur la fiche cliente la séance où elle en est, et comment son cuir chevelu a réagi à la précédente.","source":"pratique"},{"id":"ar-2","texte":"Puis les vérifications du VÍVÍVÓ™ : voir sa fiche.","source":"catalogue"}],"etapes":[{"id":"et-1","texte":"Chaque séance se rend comme un VÍVÍVÓ™ : voir sa fiche.","source":"catalogue"}],"conseils":[{"id":"co-1","texte":"Ceux du VÍVÍVÓ™.","source":"catalogue"},{"id":"co-2","texte":"Poser avec elle le rendez-vous suivant avant son départ.","source":"pratique"}],"suivi":[{"id":"su-1","texte":"Trois séances, à prix fixé.","source":"catalogue"},{"id":"su-2","texte":"Rythme des trois séances.","source":"catalogue","aValider":"L’écart entre les séances n’est pas écrit : à fixer."},{"id":"su-3","texte":"Il ouvre le programme de pousse de la Maison.","source":"maison"}]}}},"sv-plt-30-c":{"serviceId":"sv-plt-30-c","code":"PLT·30","titre":"VÍVÍVÓ™ · Le Vivifiant","validee":{"numero":1,"le":"2026-11-25T09:41:37.606Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Stimuler la pousse et densifier les zones de faiblesse : ail noir, moringa, gingembre, cannelle, en massage crânien.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"Les zones de faiblesse, les clientes qui veulent soutenir leur pousse.","source":"catalogue"},{"id":"pu-2","texte":"Pas tant que le cuir chevelu est irrité (c’est ainsi que Le Moment Cuir chevelu l’écarte).","source":"catalogue"},{"id":"pu-3","texte":"Il ouvre le programme de pousse de la Maison : DÀNDÀN™ à J+28, GBÌGBÌ™ à J+56, WÈWÈ™ à J+84, puis on remesure.","source":"maison"}],"produits":[{"id":"pr-1","texte":"Le soin VÍVÍVÓ™ : ail noir, moringa, gingembre, cannelle.","source":"catalogue","aValider":"Sa formule n’est pas au Laboratoire. À inscrire : sa composition exacte, et sous quelle forme sont le gingembre et la cannelle (poudre, macérat, huile essentielle)."}],"arrivee":[{"id":"ar-1","texte":"Regarder le cuir chevelu et les locks avant de commencer : irritation, plaie, pellicules, résidus, lock amincie à la racine. Le dire à la cliente et le noter sur sa fiche.","source":"pratique"},{"id":"ar-2","texte":"Cuir chevelu irrité : pas de VÍVÍVÓ™ aujourd’hui.","source":"catalogue"},{"id":"ar-3","texte":"Demander à la cliente si elle est enceinte ou allaite.","source":"pratique","aValider":"À décider par la Maison. Repère relevé : la fédération IFPA proscrit l’huile essentielle de cannelle écorce pendant la grossesse. Si le VÍVÍVÓ™ en contient, il ne se fait pas sur une femme enceinte."},{"id":"ar-4","texte":"Enfant : à ne pas faire sans règle écrite.","source":"pratique","aValider":"À décider par la Maison : à partir de quel âge le VÍVÍVÓ™ se fait."}],"etapes":[{"id":"et-1","texte":"Appliquer le soin sur le cuir chevelu, raie par raie.","source":"catalogue"},{"id":"et-2","texte":"Massage crânien.","source":"catalogue","detail":"20 minutes"},{"id":"et-3","texte":"Demander à la cliente ce qu’elle ressent : une chaleur est attendue, une brûlure ou une démangeaison ne l’est pas. On arrête et on rince.","source":"pratique"},{"id":"et-4","texte":"Rinçage ou non après le massage.","source":"catalogue","aValider":"À écrire."}],"conseils":[{"id":"co-1","texte":"Dire ce que le soin peut et ne peut pas : il entretient le cuir chevelu et la densité, il ne change pas la vitesse de pousse.","source":"pratique"},{"id":"co-2","texte":"Si le cuir chevelu rougit ou démange dans les heures qui suivent, rincer et nous prévenir.","source":"pratique"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : 20 min.","source":"catalogue"},{"id":"su-2","texte":"Existe en cure de trois séances.","source":"catalogue"},{"id":"su-3","texte":"Compris dans : Le Moment ; Le Moment Cuir chevelu.","source":"catalogue"},{"id":"su-4","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"sv-plt-20-c":{"serviceId":"sv-plt-20-c","code":"PLT·20","titre":"WÈWÈ™ · Détox & Purification","validee":{"numero":1,"le":"2026-11-25T09:41:37.955Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Remettre les locks et le cuir chevelu à neutre : aller chercher ce qui s’est installé en profondeur (résidus, poussière, dépôts) et l’éliminer.","source":"catalogue"},{"id":"ob-2","texte":"À la sortie : des locks propres, beaucoup moins de résidus blancs, peu ou pas d’odeurs.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"Résidus et poussière ancrés, depuis peu ou depuis longtemps ; odeurs ; cuir chevelu qui démange.","source":"catalogue"},{"id":"pu-2","texte":"Après une couleur, les Protocoles de la Maison le posent à J+45, « comme avant tout soin réparateur » ; il ferme le programme de pousse à J+84, avant de remesurer.","source":"maison"}],"produits":[{"id":"pr-1","texte":"Bain Détox Pré-Shampoing (bicarbonate, citrate de sodium, huile de neem). Se prépare à la minute, ne se garde pas.","source":"laboratoire","detail":"SH-PRE-P0","aValider":"Le Laboratoire range ce bain au niveau Prestige des lavages. À confirmer : est-ce bien le bain du WÈWÈ™ ?"},{"id":"pr-2","texte":"Shampoing Argileux Prestige : il purifie et neutralise le bain.","source":"laboratoire","detail":"SH-PRE-P1"},{"id":"pr-3","texte":"Bol de trempage en inox ou en verre, jamais en aluminium avec le bicarbonate. Thermomètre.","source":"laboratoire"}],"arrivee":[{"id":"ar-1","texte":"Regarder le cuir chevelu et les locks avant de commencer : irritation, plaie, pellicules, résidus, lock amincie à la racine. Le dire à la cliente et le noter sur sa fiche.","source":"pratique"},{"id":"ar-2","texte":"Cuir chevelu à vif ou blessé : pas de bain détox, il est alcalin et piquerait.","source":"pratique"},{"id":"ar-3","texte":"Les préparations du Laboratoire : étiquette lisible, encore dans leur délai de garde, aucune odeur rance.","source":"laboratoire"},{"id":"ar-4","texte":"Demander la date du dernier WÈWÈ™ ou d’une détox faite ailleurs.","source":"pratique","aValider":"Fréquence maximale à fixer par la Maison. Repère relevé : 2 à 4 fois par an, jamais plus (blog spécialisé, aucune source médicale)."}],"etapes":[{"id":"et-1","texte":"Préparer le bain : eau à 38 °C, poudres entièrement dissoutes, huile de neem en dernier.","source":"laboratoire"},{"id":"et-2","texte":"Immerger les longueurs. Surveiller sans s’éloigner et demander son confort à la cliente toutes les 5 minutes.","source":"laboratoire","detail":"10 à 15 minutes, jamais plus"},{"id":"et-3","texte":"Rincer abondamment à l’eau tiède. Ne jamais terminer sur le bain seul.","source":"laboratoire"},{"id":"et-4","texte":"Shampoing Argileux Prestige : obligatoire, il neutralise le bain.","source":"laboratoire"},{"id":"et-5","texte":"Rincer jusqu’à ce que l’eau soit claire, en pressant les locks.","source":"pratique"},{"id":"et-6","texte":"Sécher complètement, jusqu’au cœur des locks : une lock restée humide prend une odeur et peut moisir.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"À la maison, après chaque lavage, sécher les locks complètement avant de les attacher ou de se coucher.","source":"pratique"},{"id":"co-2","texte":"Ni cire, ni crème épaisse, ni après-shampoing dans les locks : ce sont eux qui font les résidus.","source":"pratique"},{"id":"co-3","texte":"Proposer un DÀNDÀN™ à la suite : la détox assèche.","source":"pratique"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : 1 h.","source":"catalogue"},{"id":"su-2","texte":"Compris dans : WÈWÈ™ + DÀNDÀN™ ; Abonnement : GBÈJÍ™ Trimestriel ; Le Protocole Post-Couleur ; Le Moment Cuir chevelu.","source":"catalogue"},{"id":"su-3","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"sv-forfait-sv-plt-60-wd-c":{"serviceId":"sv-forfait-sv-plt-60-wd-c","code":"PLT·60·WD","titre":"WÈWÈ™ + DÀNDÀN™ · le soin 2 en 1","validee":{"numero":1,"le":"2026-11-25T09:41:38.287Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"WÈWÈ™ + DÀNDÀN™ · le soin 2 en 1 : 2 prestations du catalogue, rendues ensemble.","source":"catalogue"},{"id":"ob-2","texte":"Rendre dans l’ordre les prestations comprises, chacune selon sa propre fiche.","source":"pratique"}],"public":[{"id":"pu-1","texte":"La cliente qui a pris cette formule : vérifier qu’elle est bien inscrite au rendez-vous.","source":"pratique"}],"produits":[{"id":"pr-1","texte":"Ceux de chaque prestation comprise : voir sa fiche, dans le même rendez-vous.","source":"catalogue"}],"arrivee":[{"id":"ar-1","texte":"Relire ce qui se rend aujourd’hui et ce qui reste à venir dans la formule.","source":"pratique"},{"id":"ar-2","texte":"Puis les vérifications de chaque prestation comprise : voir sa fiche.","source":"catalogue"}],"etapes":[{"id":"et-1","texte":"WÈWÈ™ · Détox & Purification : voir sa fiche.","source":"catalogue"},{"id":"et-2","texte":"DÀNDÀN™ · L’hydratation aux sept huiles : voir sa fiche.","source":"catalogue"}],"conseils":[{"id":"co-1","texte":"Ceux de chaque prestation rendue ce jour : voir sa fiche.","source":"catalogue"}],"suivi":[{"id":"su-1","texte":"Tout se rend le jour même.","source":"catalogue"}]}}},"sv-dds-dec":{"serviceId":"sv-dds-dec","code":"AFA·WEW·D","titre":"WÈWÈ™ avec votre produit · décapant apporté","validee":{"numero":1,"le":"2026-11-25T09:41:38.696Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Appliquer le shampoing clarifiant ou décapant fourni par la cliente, sur locks longues.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"La cliente aux locks longues qui apporte son propre clarifiant.","source":"catalogue"}],"produits":[{"id":"pr-1","texte":"Le shampoing clarifiant ou décapant de la cliente.","source":"catalogue","aValider":"Que fait-on d’un produit que la Maison juge trop agressif ? À décider."}],"arrivee":[{"id":"ar-1","texte":"Regarder le cuir chevelu et les locks avant de commencer : irritation, plaie, pellicules, résidus, lock amincie à la racine. Le dire à la cliente et le noter sur sa fiche.","source":"pratique"},{"id":"ar-2","texte":"Lire l’étiquette avec la cliente : ce que c’est, son mode d’emploi, son temps de pose, sa date. Lui demander si elle l’a déjà utilisé sans réaction.","source":"pratique"},{"id":"ar-3","texte":"Cuir chevelu à vif ou blessé : pas de décapant aujourd’hui.","source":"pratique"}],"etapes":[{"id":"et-1","texte":"Mouiller abondamment à l’eau tiède, jusqu’au cœur des locks.","source":"pratique"},{"id":"et-2","texte":"Appliquer le produit de la cliente, selon son mode d’emploi.","source":"catalogue","detail":"Selon l’étiquette du produit"},{"id":"et-3","texte":"Rincer jusqu’à ce que l’eau soit claire, en pressant les locks.","source":"pratique"},{"id":"et-4","texte":"Sécher complètement, jusqu’au cœur des locks : une lock restée humide prend une odeur et peut moisir.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"À la maison, après chaque lavage, sécher les locks complètement avant de les attacher ou de se coucher.","source":"pratique"},{"id":"co-2","texte":"Proposer un DÀNDÀN™ à la suite : un décapant assèche.","source":"pratique"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : 1 h.","source":"catalogue"},{"id":"su-2","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"sv-dds-soi-c":{"serviceId":"sv-dds-soi-c","code":"AFA·WEW·S","titre":"WÈWÈ™ avec votre produit · masque ou huile apportés","validee":{"numero":1,"le":"2026-11-25T09:41:39.094Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Appliquer le soin, le masque ou l’huile fourni par la cliente.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"La cliente qui apporte son propre soin.","source":"catalogue"}],"produits":[{"id":"pr-1","texte":"Le soin, le masque ou l’huile de la cliente.","source":"catalogue","aValider":"Que fait-on d’un produit qui laisse des résidus dans les locks (cire, beurre épais) ? À décider."}],"arrivee":[{"id":"ar-1","texte":"Regarder le cuir chevelu et les locks avant de commencer : irritation, plaie, pellicules, résidus, lock amincie à la racine. Le dire à la cliente et le noter sur sa fiche.","source":"pratique"},{"id":"ar-2","texte":"Lire l’étiquette avec la cliente : ce que c’est, son mode d’emploi, son temps de pose, sa date. Lui demander si elle l’a déjà utilisé sans réaction.","source":"pratique"},{"id":"ar-3","texte":"Locks propres avant le soin.","source":"pratique"}],"etapes":[{"id":"et-1","texte":"Appliquer le produit de la cliente sur les longueurs, lock par lock, selon son mode d’emploi.","source":"catalogue","detail":"Selon l’étiquette du produit"},{"id":"et-2","texte":"Rincer si le mode d’emploi le demande, jusqu’à ce que l’eau soit claire.","source":"pratique"},{"id":"et-3","texte":"Sécher complètement, jusqu’au cœur des locks : une lock restée humide prend une odeur et peut moisir.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"Dormir avec un bonnet en satin ou en soie.","source":"laboratoire"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : 45 min.","source":"catalogue"},{"id":"su-2","texte":"Mettre à jour la fiche cliente : ce qui a été fait, ce qui a été vu.","source":"catalogue"}]}}},"sv-plt-50-eve-c":{"serviceId":"sv-plt-50-eve-c","code":"PLT·50·EVE","titre":"La sortie de grand jour · coiffure exception","validee":{"numero":1,"le":"2026-11-25T09:41:39.428Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Un attaché sophistiqué, avec un ornement au choix (dorures, foulard, perles), qui tient toute la journée et la soirée.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"La cliente qui a un événement le jour même ou le lendemain.","source":"catalogue"}],"produits":[{"id":"pr-1","texte":"Huile parfumée, élastiques, pinces. Les ornements viennent de la Gamme.","source":"catalogue","aValider":"Référence de l’huile parfumée utilisée au salon : à inscrire."},{"id":"pr-2","texte":"Ornements au choix : dorures, foulard, perles.","source":"catalogue"}],"arrivee":[{"id":"ar-1","texte":"Demander l’heure et la durée de l’événement, la tenue, et l’ornement choisi.","source":"pratique"},{"id":"ar-2","texte":"Locks sèches avant de coiffer.","source":"pratique"},{"id":"ar-3","texte":"Regarder les racines : sur une racine amincie ou une zone dégarnie, pas de coiffure qui tire.","source":"pratique"}],"etapes":[{"id":"et-1","texte":"Attaché sophistiqué, construit pour tenir la journée et la soirée.","source":"catalogue"},{"id":"et-2","texte":"Pose de l’ornement choisi.","source":"catalogue"},{"id":"et-3","texte":"Aucune tension à la racine : si la cliente dit que ça tire, on desserre tout de suite.","source":"pratique"},{"id":"et-4","texte":"Faire bouger la tête à la cliente avant qu’elle parte : rien ne doit glisser ni tirer.","source":"pratique"}],"conseils":[{"id":"co-1","texte":"Défaire la coiffure après l’événement : elle n’est pas faite pour être gardée plusieurs jours.","source":"pratique"},{"id":"co-2","texte":"Si elle tire ou donne mal à la tête, la desserrer sans attendre.","source":"pratique"}],"suivi":[{"id":"su-1","texte":"Durée au catalogue : 45 min.","source":"catalogue"},{"id":"su-2","texte":"Compris dans : Abonnement : GBÈJÍ™ Trimestriel ; YÈKPÈ™ × 3 ; Abonnement : GBÈJÍ™ Annuel.","source":"catalogue"}]}}},"sv-plt-50-sty-s":{"serviceId":"sv-plt-50-sty-s","code":"PLT·50·STY·S","titre":"La sortie Signature · coiffure élaborée","validee":{"numero":1,"le":"2026-11-25T09:41:39.762Z","par":"la direction (validée sur la page des fiches le 25 novembre 2026)","contenu":{"objectif":[{"id":"ob-1","texte":"Une coiffure de sortie travaillée : volume, séparation nette, finition longue tenue.","source":"catalogue"}],"public":[{"id":"pu-1","texte":"La cliente qui veut une coiffure élaborée en sortant du rituel.","source":"catalogue"}],"produits":[{"id":"pr-1","texte":"Huile parfumée, élastiques, pinces. Les ornements viennent de la Gamme.","source":"catalogue","aValider":"Référence de l’huile parfumée utilisée au salon : à inscrire."}],"arrivee":[{"id":"ar-1","texte":"S’accorder avec la cliente sur la coiffure, photo à l’appui si elle en a une.","source":"pratique"},{"id":"ar-2","texte":"Locks sèches avant de coiffer.","source":"pratique"},{"id":"ar-3","texte":"Regarder les racines : sur une racine amincie ou une zone dégarnie, pas de coiffure qui tire.","source":"pratique"}],"etapes":[{"id":"et-1","texte":"Séparations nettes, puis construction du volume.","source":"catalogue"},{"id":"et-2","texte":"Finition longue tenue.","source":"catalogue"}